type Story = StoryObj<InLineAlertProps>;

/**
 * ```ts
 * import { InLineAlert } from '@adobe-commerce/elsie/components/InLineAlert';
 * ```
 * ```tsx
 * <InLineAlert
 *  heading="In Line Alert heading"
 *  description="Description of the In Line Alert"
 *  type="warning"
 *  additionalActions={[
 *   {
 *    label: 'Action 1',
 *    onClick: ()=>{},
 *   },
 *  ]}
 * />
 * ```
 */

export const InLineAlert: Story = {
  args: {
    heading: 'In Line Alert heading',
    description: 'Description of the In Line Alert',
    type: 'warning',
    //@ts-ignore
    icon: IconsList.WarningFilled,
    additionalActions: [
      {
        label: 'Action',
        onClick: action('Action clicked'),
      },
    ],
  },
};

